// Reference solution
function overlaps(a, b) {
  var as = Date.parse(a.startAt), ae = Date.parse(a.endAt);
  var bs = Date.parse(b.startAt), be = Date.parse(b.endAt);
  return as < be && bs < ae;   // half-open [start, end): touching ends do not overlap
}

